// Lancer la recolte : passe la demande a l'outil maison recolte_youtube (recolte_lancer.py)
const fs = require('fs'), cp = require('child_process'), os = require('os'), path = require('path');
const i = $('Execute Workflow Trigger').first().json;
const BASE = $env.ARCHI_BASE || path.join(os.homedir(), '.n8n-files');
const dossier = path.join(BASE, 'outils', 'recolte_youtube');
const f = path.join(os.tmpdir(), 'recolte_cmd_' + Date.now() + '.json');
fs.writeFileSync(f, JSON.stringify({ cible: String(i.cible || ''), question: String(i.question || '') }), 'utf8');
let out = '';
try {
  out = cp.execFileSync($env.ARCHI_PY || 'python', [path.join(dossier, 'recolte_lancer.py'), '--fichier', f],
    { cwd: dossier, timeout: 300000, windowsHide: true, encoding: 'utf8', env: Object.assign({}, process.env, { PYTHONIOENCODING: 'utf-8' }) });
} catch (e) { out = String(e.stdout || ''); }
try { fs.unlinkSync(f); } catch (e) {}
let r;
try { r = JSON.parse(String(out).trim().split(/\r?\n/).pop()); } catch (e) {
  return [{ json: { resultat: "ERREUR : la recolte n'a pas repondu (recolte_lancer.py).", phrase_pour_utilisateur: 'La recolte a eu un souci technique.' } }];
}
return [{ json: { ok: r.ok, resultat: r.resultat, phrase_pour_utilisateur: r.phrase_pour_utilisateur } }];

// Lecteur de pages LOCAL (Scrapling, sur le PC) avant Tavily : gratuit, passe la plupart des protections.
// Si la lecture rate ou si la page est presque vide, on passe la main a Tavily (noeud suivant).
const cp = require('child_process'), fs = require('fs'), pr = require('process');
const url = String($('Execute Workflow Trigger').first().json.cible || '').trim();
const PY = ($env.ARCHI_PY || 'python');
const f = ($env.ARCHI_BASE || '') + '/page_demande_' + Date.now() + '.json';
fs.writeFileSync(f, JSON.stringify({ url, max_caracteres: 9000, furtif: 'auto' }), 'utf8');
let r = { ok: false };
try {
  const out = await new Promise((ok, ko) => cp.execFile(PY, [($env.ARCHI_DEPOT || '') + '/pc/lire_page/lire_page.py', '--fichier', f],
    { timeout: 75000, windowsHide: true, maxBuffer: 32 * 1024 * 1024, env: Object.assign({}, pr.env, { PYTHONIOENCODING: 'utf-8' }) },
    (e, so) => (e && !so) ? ko(e) : ok(String(so || ''))));
  r = JSON.parse(out.trim().split(/\r?\n/).pop());
} catch (e) { r = { ok: false, erreur: String(e.message || e).slice(0, 200) }; }
try { fs.unlinkSync(f); } catch (e) {}
if (r.ok && r.texte && String(r.texte).length > 300) {
  const t = String(r.texte);
  return [{ json: { lu: true, moteur: r.moteur, resultat: 'CONTENU DE LA PAGE ' + url + (r.titre ? ' (« ' + r.titre + ' »)' : '') + (r.coupe ? ' (début seulement)' : '') + ' :\n\n' + t + '\n\nRésume pour l’utilisateur ce qui répond à sa demande, sans inventer, et cite la page.' } }];
}
if (r.phrase_pour_utilisateur && /404|n'existe pas|locales/.test(r.phrase_pour_utilisateur)) return [{ json: { lu: true, resultat: r.phrase_pour_utilisateur } }];
return [{ json: { lu: false, cible: url, erreur_local: r.erreur || r.phrase_pour_utilisateur || '' } }];
